contract InvMutTest {
    C public c;

    constructor(C _c) { c = _c; }

    // Call sequence:
    // 1) Caller A (the test contract) attempts to setL1BlockValues with a provided _number by calling c.setL1BlockValues(...).
    // On the original contract P this must revert unless msg.sender == DEPOSITOR_ACCOUNT, so number stays unchanged.
    // On mutant M the call will succeed and number will be set to the supplied value.

    function run(uint64 newNumber, uint64 other_ts, uint256 other_basefee, bytes32 other_hash, uint64 other_seq, bytes32 other_batcherHash, uint256 other_overhead, uint256 other_scalar) external {
        // Read original number
        uint64 before = c.number();

        // Attempt to set values from this contract's address (not the DEPOSITOR_ACCOUNT)
        // This is a state-changing call and must be a top-level statement.
        c.setL1BlockValues(newNumber, other_ts, other_basefee, other_hash, other_seq, other_batcherHash, other_overhead, other_scalar);

        // Read resulting number
        uint64 after = c.number();

        // The distinguishing rule: if the call came from a non-depositor (this contract), the stored number must NOT change.
        // Expressed as: after == before
        assert(after == before);
    }

    // Allow contract to receive ETH in case needed by caller externally
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // take caller address as input to simulate who is calling setL1BlockValues
    // and all parameters forwarded to setL1BlockValues
    function run(address caller,
                 uint64 _number,
                 uint64 _timestamp,
                 uint256 _basefee,
                 bytes32 _hash,
                 uint64 _sequenceNumber,
                 bytes32 _batcherHash,
                 uint256 _l1FeeOverhead,
                 uint256 _l1FeeScalar) public payable {
        require(caller != address(0));

        // perform call as the supplied caller using low-level call to set msg.sender
        // Build calldata for setL1BlockValues
        bytes memory data = abi.encodeWithSelector(
            c.setL1BlockValues.selector,
            _number,
            _timestamp,
            _basefee,
            _hash,
            _sequenceNumber,
            _batcherHash,
            _l1FeeOverhead,
            _l1FeeScalar
        );

        // Execute call from the provided caller using assembly to set msg.sender via a call to a minimal proxy: use call with address 'caller' as sender is not possible in Solidity.
        // Instead, require that caller == address(this) or rely on revert observation only when msg.sender != DEPOSITOR_ACCOUNT.
        // To simulate differing callers without helpers, we restrict to two cases: if caller == address(this) we perform the call directly (msg.sender == this),
        // otherwise we perform a call that will originate from the external caller via a revert observation by using require to ensure caller is either address(this) or DEPOSITOR_ACCOUNT.

        // For generality and to avoid creating additional contracts, we observe behavior when the test contract itself calls (msg.sender == address(this)).
        // We assert the property relating caller to revert: if the caller is not the depositor address returned by c.DEPOSITOR_ACCOUNT(), then the call must revert.

        bool reverted;
        // Only perform the call from this contract; treat provided `caller` as the intended caller and compare to c.DEPOSITOR_ACCOUNT()
        try c.setL1BlockValues(_number, _timestamp, _basefee, _hash, _sequenceNumber, _batcherHash, _l1FeeOverhead, _l1FeeScalar) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // The rule: reverted == (caller != c.DEPOSITOR_ACCOUNT())
        // This asserts that calls are allowed exactly when the provided caller equals the depositor account.
        assert(reverted == (caller != c.DEPOSITOR_ACCOUNT()));
    }

    receive() external payable {}
}

