pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint64 _number, uint64 _timestamp, uint256 _basefee, bytes32 _hash, uint64 _sequenceNumber, bytes32 _batcherHash, uint256 _l1FeeOverhead, uint256 _l1FeeScalar) public {
        // keep values wide; no restrictive assumes needed
        // call as the depositor account
        address depositor = C.DEPOSITOR_ACCOUNT();
        vm.prank(depositor);
        c.setL1BlockValues(_number, _timestamp, _basefee, _hash, _sequenceNumber, _batcherHash, _l1FeeOverhead, _l1FeeScalar);

        // General rule: sequenceNumber getter equals the provided _sequenceNumber parameter
        // This is true for the reference contract; the mutant sets sequenceNumber = _number and will fail when _number != _sequenceNumber
        assertTrue(c.sequenceNumber() == _sequenceNumber);
    }
}

