pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    // depositor account from the contract
    address constant DEPOSITOR = 0xDeaDDEaDDeAdDeAdDEAdDEaddeAddEAdDEAd0001;

    function setUp() public { c = new C(); }

    // fuzz the prior stored value and the incoming _sequenceNumber
    function testFuzz_property(uint64 priorSequence, uint64 incomingSequence) public {
        // keep domain wide but non-restrictive; allow all uint64 values
        // Ensure we can set an initial sequenceNumber by calling setL1BlockValues from depositor
        // Use vm.prank to act as depositor. We need other params for the call; fuzzing only the deciding params.

        // initial call to set a prior sequenceNumber to priorSequence
        vm.prank(DEPOSITOR);
        c.setL1BlockValues(
            /* _number */ 1,
            /* _timestamp */ 1,
            /* _basefee */ 1,
            /* _hash */ bytes32(0),
            /* _sequenceNumber */ priorSequence,
            /* _batcherHash */ bytes32(0),
            /* _l1FeeOverhead */ 0,
            /* _l1FeeScalar */ 0
        );

        // now call setL1BlockValues again with incomingSequence
        vm.prank(DEPOSITOR);
        c.setL1BlockValues(
            /* _number */ 2,
            /* _timestamp */ 2,
            /* _basefee */ 2,
            /* _hash */ bytes32(1),
            /* _sequenceNumber */ incomingSequence,
            /* _batcherHash */ bytes32(1),
            /* _l1FeeOverhead */ 1,
            /* _l1FeeScalar */ 1
        );

        // General rule: after the second call, the stored sequenceNumber equals the most-recent provided _sequenceNumber.
        // This holds for the reference (assignment). The mutant that increments will produce prior+incoming when prior != 0,
        // thus violating the rule for many fuzzed inputs. We assert that c.sequenceNumber() == incomingSequence.
        assertTrue(c.sequenceNumber() == incomingSequence);
    }
}

