pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address constant DEPOSITOR = 0xDeaDDEaDDeAdDeAdDEAdDEaddeAddEAdDEAd0001;

    function setUp() public { c = new C(); }

    function testFuzz_property(bytes32 fuzzBatcherHash) public {
        // keep the domain wide; no need to restrict fuzzBatcherHash
        // Must act as the depositor to call setL1BlockValues
        vm.prank(DEPOSITOR);
        c.setL1BlockValues(
            uint64(1), // _number
            uint64(2), // _timestamp
            uint256(3), // _basefee
            bytes32(4), // _hash
            uint64(5), // _sequenceNumber
            fuzzBatcherHash, // _batcherHash (fuzzed deciding parameter)
            uint256(6), // _l1FeeOverhead
            uint256(7)  // _l1FeeScalar
        );

        // The reference implementation always stores exactly the provided _batcherHash.
        // The mutant stores bytes32(0) instead. This assertion holds for all inputs on the reference
        // and will fail for some inputs (any non-zero fuzzBatcherHash) on the mutant.
        assertTrue(c.batcherHash() == fuzzBatcherHash);
    }
}
